/* LES RAPPELS QUOTIDIENS (web push). Le serveur (Edge Function push-envoyer) envoie JSON {titre, corps, url, tag} ; le texte
   est écrit là-bas, jamais ici. ⛔ TOUJOURS afficher une notification : sur iOS un push silencieux fait RÉVOQUER l'abonnement
   — une charge illisible ou vide montre donc quand même « Alaq ». L'icône est le logo doré (jamais une cloche : Muslim), pas
   d'emoji. Le plan et l'abonnement vivent dans rappels.js. Garde : outils/verifier-sw-horsligne.mjs (S6).
   (journal : sw.js · les rappels, étape 2) */
self.addEventListener('push',e=>{
  let d={};
  try{ d=e.data?e.data.json():{}; }catch(_){ try{ d={corps:e.data.text()}; }catch(__){ d={}; } }
  if(!d||typeof d!=='object')d={};
  e.waitUntil(self.registration.showNotification(String(d.titre||'Alaq').slice(0,120),{
    body:String(d.corps||'Ta leçon du jour t’attend').slice(0,240),
    icon:new URL('icone-alaq-192.png',self.location.href).href,
    tag:String(d.tag||'alaq-rappel'),
    renotify:true,   // un rappel d'hier resté sans réponse est REMPLACÉ, et celui d'aujourd'hui sonne quand même
    lang:'fr',
    data:{url:String(d.url||RACINE_SW)}
  }));
});
/* Un toucher ouvre l'app : la fenêtre déjà ouverte sur l'app prend le premier plan, sinon une neuve s'ouvre. ⛔ Jamais une
   autre page de la même origine (le pupitre et le studio y sont servis aussi) ni une adresse d'ailleurs. */
self.addEventListener('notificationclick',e=>{
  e.notification.close();
  let cible=new URL(RACINE_SW,self.location.origin).href;
  try{ const u=new URL(String((e.notification.data&&e.notification.data.url)||RACINE_SW),self.location.origin); if(u.origin===self.location.origin)cible=u.href; }catch(_){}
  e.waitUntil((async()=>{
    try{
      const ouverte=(await self.clients.matchAll({type:'window',includeUncontrolled:true})).find(_racineDeLApp);
      if(ouverte){ await ouverte.focus(); return; }
    }catch(_){}
    try{ await self.clients.openWindow(cible); }catch(_){}
  })());
});
self.addEventListener('fetch',e=>{
  /* ⛔ Ne jamais intercepter une requête Range : Safari streame l'audio par tranches et exige
     un 206 ; un 200 complet venu du cache est refusé. (journal : sw.js · les requêtes Range) */
  if(e.request.headers.get('range'))return;
  const url=new URL(e.request.url);
  /* Navigation / index : cache versionné d'abord, réseau si vide. Seules la racine et
     index.html sont « l'index » ; une autre navigation hors CORE reçoit index.html mais rien
     n'est écrit. ⛔ Ne jamais réécrire l'ancien cache (index.html neuf + app.css ancien) : on
     n'écrit qu'en cas de trou. (journal : sw.js · la navigation et l'ancien cache réécrit) */
  const versIndex=url.pathname===RACINE_SW||url.pathname.endsWith('/index.html');
  if(versIndex||(e.request.mode==='navigate'&&!COEUR.has(url.pathname))){
    e.respondWith((async()=>{
      const c=await caches.open(CACHE);
      const hit=await c.match('index.html');
      if(hit)return hit;   // le cache d'abord : l'app s'ouvre TOUT DE SUITE, même si le réseau traîne
      try{
        const r=await fetch(e.request);
        if(r&&r.ok&&versIndex)c.put('index.html',r.clone());   // jamais un 500 ni un portail captif, jamais une autre page
        return r;
      }catch(_){return (await caches.match('.'))||Response.error();}
    })());
    return;
  }
  /* Le cœur (CORE) : cache versionné d'abord, réseau en secours. ⚠️ Pré-cacher ne suffit pas,
     c'est cette branche qui SERT le cœur hors ligne. (journal : sw.js · pré-cacher ne servait à rien) */
  if(url.origin===self.location.origin&&COEUR.has(url.pathname)){
    e.respondWith((async()=>{
      const c=await caches.open(CACHE);
      const hit=await c.match(e.request,{ignoreSearch:true});
      if(hit)return hit;
      try{
        const r=await fetch(e.request);
        if(r&&r.ok)c.put(e.request,r.clone());
        return r;
      }catch(_){return (await caches.match(e.request,{ignoreSearch:true}))||Response.error();}
    })());
    return;
  }
  // audios, polices Google, récitation, icônes : cache d'abord
  const cacheFirst=url.pathname.indexOf('/audios-app-alaq/')>=0
    ||url.hostname==='fonts.googleapis.com'||url.hostname==='fonts.gstatic.com'||url.hostname==='cdn.jsdelivr.net'
    ||url.hostname==='cdn.islamic.network'  // la récitation streamée : mise en cache côté client, comme leurs conditions le demandent
    ||url.pathname.indexOf('/coran/')>=0&&/-v1\.json$/.test(url.pathname)  // une sourate du lecteur (données de l'app, nom versionné)
    ||/\.(png|jpe?g|webp|mp3|mp4|woff2?)$/.test(url.pathname);
  /* ⛔ Les fichiers de quran.com (voix d'un mot, horaires, versets) ne sont JAMAIS gardés : leurs conditions limitent le cache à 7 jours,
     le cache HTTP du navigateur s'en charge (journal : sw.js · les voix de quran.com) */
  if(cacheFirst&&!/(^|\.)(qurancdn\.com|quran\.com|quranicaudio\.com|everyayah\.com)$/.test(url.hostname)){
    e.respondWith((async()=>{
      const hit=await caches.match(e.request);
      if(hit)return hit;
      try{
        const r=await fetch(e.request);
        // les IMAGES vont dans leur cache versionné ; sons, polices, récitation dans MEDIA
        if(r&&(r.ok||r.type==='opaque')){
          const img=/\.(png|jpe?g|webp|gif)$/.test(url.pathname);
          const c=await caches.open(img?IMGCACHE:MEDIA);c.put(e.request,r.clone());
        }
        return r;
      }catch(_){return Response.error();}
    })());
  }
});
